import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.DbIb1qZn.js";const k=JSON.parse('{"title":"Bundles (.frc)","description":"What a Frensense bundle is, how to download and use one, and how to judge whether it helps on your code.","frontmatter":{"title":"Bundles (.frc)","description":"What a Frensense bundle is, how to download and use one, and how to judge whether it helps on your code."},"headers":[],"relativePath":"bundles.md","filePath":"bundles.md"}'),n={name:"bundles.md"};function r(h,e,l,o,d,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="bundles-frc" tabindex="-1">Bundles (<code>.frc</code>) <a class="header-anchor" href="#bundles-frc" aria-label="Permalink to &quot;Bundles (\`.frc\`)&quot;">​</a></h1><p>Frensense ships with a built-in knowledge pack: 1,627 facts about sources, sinks and sanitizers for the languages it supports. A <strong>bundle</strong> is an extra pack you load on top, for frameworks and libraries the built-in pack does not know. If a scan misses a vulnerability because the engine has never heard of your web framework&#39;s request object or database call, a bundle is how you tell it.</p><p>A <code>.frc</code> file is a versioned, checksummed archive of two things:</p><ol><li><strong>Learned facts</strong>: sources, sinks, sanitizers and policy checks that the engine merges into its tables at scan time. A learned sink takes part in the same graph analysis as a built-in one, so taint paths and guards apply to it.</li><li><strong>Patterns</strong>: vulnerable and fixed examples with their CWE, impact and severity, kept so you can see what the bundle was taught from.</li></ol><p>A bundle is data, not code. It cannot run anything. It can change what the engine reports, in both directions (see &quot;Check that a bundle helps&quot;).</p><h2 id="use-a-bundle" tabindex="-1">Use a bundle <a class="header-anchor" href="#use-a-bundle" aria-label="Permalink to &quot;Use a bundle&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./src</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my.frc</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # -b is the short form</span></span></code></pre></div><p>Other ways the engine finds one, in the order it looks:</p><table tabindex="0"><thead><tr><th>How</th><th>Applies to</th></tr></thead><tbody><tr><td><code>-b</code> / <code>--bundle &lt;file&gt;</code> on the command line</td><td>CLI scans</td></tr><tr><td><code>frensense-corpus.frc</code> in the scanned folder</td><td>CLI scans (found automatically)</td></tr><tr><td><code>FRENSENSE_CORPUS_BUNDLE</code> environment variable</td><td>the MCP and LSP servers only</td></tr><tr><td><code>corpus_bundle</code> argument on an MCP tool call</td><td>MCP</td></tr></tbody></table><p><code>FRENSENSE_CORPUS_BUNDLE</code> does not affect a plain <code>frensense .</code> scan. Use <code>-b</code> or the auto-discovered file there.</p><p>To see what a bundle contains:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my.frc</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # add --json for machine output</span></span></code></pre></div><h2 id="community-bundles" tabindex="-1">Community bundles <a class="header-anchor" href="#community-bundles" aria-label="Permalink to &quot;Community bundles&quot;">​</a></h2><p>Free starter bundles are published for the main stacks. Each has a datasheet that lists the classes it covers and the examples it was checked against.</p><table tabindex="0"><thead><tr><th>Bundle</th><th>For</th></tr></thead><tbody><tr><td><a href="https://bundles.friehub.cloud/community/latest/frensense-typescript.frc" target="_blank" rel="noreferrer"><code>frensense-typescript.frc</code></a></td><td>TypeScript and JavaScript (Node.js, Express, Next.js)</td></tr><tr><td><a href="https://bundles.friehub.cloud/community/latest/frensense-python.frc" target="_blank" rel="noreferrer"><code>frensense-python.frc</code></a></td><td>Python (Flask, Django, scripts)</td></tr><tr><td><a href="https://bundles.friehub.cloud/community/latest/frensense-go.frc" target="_blank" rel="noreferrer"><code>frensense-go.frc</code></a></td><td>Go (HTTP handlers, templates, SQL drivers)</td></tr><tr><td><a href="https://bundles.friehub.cloud/community/latest/frensense-c.frc" target="_blank" rel="noreferrer"><code>frensense-c.frc</code></a></td><td>C (memory safety: use after free, leaks, buffer bounds)</td></tr><tr><td><a href="https://bundles.friehub.cloud/community/latest/frensense-master.frc" target="_blank" rel="noreferrer"><code>frensense-master.frc</code></a></td><td>All of the above in one file</td></tr></tbody></table><p>Alongside them: <a href="https://bundles.friehub.cloud/community/latest/CWE_DATASHEET.md" target="_blank" rel="noreferrer"><code>CWE_DATASHEET.md</code></a>, <a href="https://bundles.friehub.cloud/community/latest/SHA256SUMS" target="_blank" rel="noreferrer"><code>SHA256SUMS</code></a> and its signature <a href="https://bundles.friehub.cloud/community/latest/SHA256SUMS.sig" target="_blank" rel="noreferrer"><code>SHA256SUMS.sig</code></a>. Check a download before you use it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSLO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://bundles.friehub.cloud/community/latest/frensense-python.frc</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSLO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://bundles.friehub.cloud/community/latest/SHA256SUMS</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-missing</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span></span></code></pre></div><p>Commercial bundles with broader framework coverage are offered separately. <a href="https://www.friehub.cloud/contact" target="_blank" rel="noreferrer">Get in touch</a> for details.</p><h2 id="check-that-a-bundle-helps" tabindex="-1">Check that a bundle helps <a class="header-anchor" href="#check-that-a-bundle-helps" aria-label="Permalink to &quot;Check that a bundle helps&quot;">​</a></h2><p>More knowledge is not automatically better. A bundle that teaches the engine a very common function name as a sink can flood a large codebase with false alarms, and slow the scan down. Before you rely on one in CI, run it against your own code both ways:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./src</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bare.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./src</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my.frc</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> with-bundle.json</span></span></code></pre></div><p>Compare <code>advisory_count</code> in the two files. Then read a sample of the findings that only the bundle produced and ask whether each one is a real problem. If most are not, do not use that bundle on this code, and report it so it can be fixed. A bundle&#39;s own datasheet describes the examples it was verified on, not how it behaves on your project.</p><h2 id="make-your-own" tabindex="-1">Make your own <a class="header-anchor" href="#make-your-own" aria-label="Permalink to &quot;Make your own&quot;">​</a></h2><p>You teach the engine with pairs of labelled examples: one vulnerable, one fixed. The bundler replays each pair through the engine, learns the facts that separate them, and keeps a fact only if it survives checks against every other pair. A fact backed by one family is marked <code>provisional</code>; two or more make it <code>confirmed</code>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mycorpus</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --strict</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # check the examples first</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mycorpus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my.frc</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # compile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frensense</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bundle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my.frc</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # read what was actually published</span></span></code></pre></div><p>Start with <a href="/guide/teachability">How teaching works</a>, then the <a href="/corpus/authoring">authoring guide</a>.</p>`,26)])])}const u=s(n,[["render",r]]);export{k as __pageData,u as default};
